export class BulkheadSemaphore {
  private inFlight = 0;

  constructor(private maxConcurrent: number, private maxQueue: number) {}

  async execute<T>(action: () => Promise<T>): Promise<T> {
    if (this.inFlight >= this.maxConcurrent + this.maxQueue) {
      // Bulkhead capacity saturated! Reject immediately to preserve other services
      throw new Error('Bulkhead capacity exceeded (Shedding load)');
    }

    this.inFlight++;
    try {
      return await action();
    } finally {
      this.inFlight--;
    }
  }
}
